import {
  computed,
  defineComponent,
  h,
  isRef,
  onBeforeUnmount,
  onMounted,
  shallowRef,
  watch,
  type PropType,
} from "vue";
import { UniversalPlayer as CoreUniversalPlayer } from "../../core/player.js";
import { sourceToken } from "../../core/source.js";
import { createInitialState } from "../../core/state.js";
import type {
  CaptionsOptions,
  Chapter,
  ControlsMode,
  PlaylistOptions,
  PlayerEvent,
  PlayerOptions,
  PlayerSourceInput,
  PlayerState,
  SurveySource,
  ThemeMode,
  ThumbnailTrack,
} from "../../core/types.js";

export type MaybeRef<T> = T | { readonly value: T };

function read<T>(value: MaybeRef<T> | undefined): T | undefined {
  if (value === undefined) {
    return undefined;
  }

  return isRef(value) ? (value.value as T) : (value as T);
}

export type PlayerOptionKey = keyof Omit<PlayerOptions, "container">;

/** Reactive inputs accepted by the Vue composable. */
export type UseUniversalPlayerOptions = {
  readonly [K in PlayerOptionKey]?: MaybeRef<Omit<PlayerOptions, "container">[K]>;
} & { readonly host: MaybeRef<HTMLElement | null> };

/** Result returned by {@link useUniversalPlayer}. */
export interface UseUniversalPlayerResult {
  readonly state: { readonly value: PlayerState };
  readonly player: { readonly value: CoreUniversalPlayer | null };
  play(): Promise<void>;
  pause(): void;
  seek(time: number): void;
  load(source: PlayerSourceInput): Promise<void>;
  destroy(): void;
}

function resolveOptions(options: UseUniversalPlayerOptions): Omit<PlayerOptions, "container"> {
  const resolved: Record<string, unknown> = {};

  for (const key of Object.keys(options) as Array<keyof UseUniversalPlayerOptions>) {
    if (key === "host") {
      continue;
    }

    const value = read(options[key] as MaybeRef<unknown>);

    if (value !== undefined) {
      resolved[key] = value;
    }
  }

  return resolved as Omit<PlayerOptions, "container">;
}

/**
 * Creates and maintains one player for the lifetime of a Vue component.
 *
 * Works with Vue 2.7 and Vue 3 through the shared Composition API surface.
 */
export function useUniversalPlayer(options: UseUniversalPlayerOptions): UseUniversalPlayerResult {
  const state = shallowRef<PlayerState>(createInitialState());
  const player = shallowRef<CoreUniversalPlayer | null>(null);

  let instance: CoreUniversalPlayer | null = null;
  let unsubscribes: Array<() => void> = [];

  const connect = (): void => {
    const host = read(options.host);

    if (host === null || host === undefined || instance !== null) {
      return;
    }

    const created = new CoreUniversalPlayer({
      ...resolveOptions(options),
      container: host,
    });
    instance = created;
    player.value = created;
    state.value = created.state;

    unsubscribes = [
      created.on("statechange", (next) => {
        state.value = next;
      }),
      created.on("timeupdate", (event) => {
        state.value = {
          ...state.value,
          currentTime: event.currentTime,
          duration: event.duration,
          buffered: event.buffered,
        };
      }),
    ];

    const source = read(options.source);

    if (source !== undefined) {
      void created.load(source).catch(() => {
        // Failures are published through state and the `error` event.
      });
    }
  };

  const destroy = (): void => {
    for (const unsubscribe of unsubscribes) {
      unsubscribe();
    }

    unsubscribes = [];
    instance?.destroy();
    instance = null;
    player.value = null;
  };

  onMounted(connect);
  onBeforeUnmount(destroy);

  watch(
    () => sourceToken(read(options.source)),
    () => {
      const source = read(options.source);

      if (instance !== null && source !== undefined) {
        void instance.load(source).catch(() => {
          // Failures are published through state and the `error` event.
        });
      }
    },
  );

  watch(
    () => read(options.volume),
    (value) => {
      if (instance !== null && value !== undefined) {
        instance.setVolume(value);
      }
    },
  );

  watch(
    () => read(options.muted),
    (value) => {
      if (instance !== null && value !== undefined) {
        instance.setMuted(value);
      }
    },
  );

  watch(
    () => read(options.playbackRate),
    (value) => {
      if (instance !== null && value !== undefined) {
        instance.setPlaybackRate(value);
      }
    },
  );

  return {
    state,
    player,
    async play(): Promise<void> {
      await instance?.play();
    },
    pause(): void {
      instance?.pause();
    },
    seek(time: number): void {
      instance?.seek(time);
    },
    async load(source: PlayerSourceInput): Promise<void> {
      await instance?.load(source);
    },
    destroy,
  };
}

/**
 * Vue host component.
 *
 * The same component works in Vue 2.7 and Vue 3.
 */
export const UniversalPlayer = defineComponent({
  name: "UniversalPlayer",
  props: {
    src: { type: [String, Object] as PropType<PlayerSourceInput>, default: undefined },
    controls: { type: String as PropType<ControlsMode>, default: undefined },
    theme: { type: String as PropType<ThemeMode>, default: undefined },
    locale: { type: String, default: undefined },
    autoplay: { type: Boolean, default: undefined },
    muted: { type: Boolean, default: undefined },
    loop: { type: Boolean, default: undefined },
    poster: { type: String, default: undefined },
    volume: { type: Number, default: undefined },
    playbackRate: { type: Number, default: undefined },
    chapters: { type: Array as PropType<readonly Chapter[]>, default: undefined },
    thumbnails: { type: Object as PropType<ThumbnailTrack>, default: undefined },
    captions: { type: Object as PropType<CaptionsOptions>, default: undefined },
    survey: {
      type: [Object, Function] as PropType<SurveySource>,
      default: undefined,
    },
    playlist: { type: Object as PropType<PlaylistOptions>, default: undefined },
    keyboard: { type: Boolean, default: true },
    clickToPlay: { type: Boolean, default: true },
    autoHideControls: { type: Boolean, default: true },
    seekStep: { type: Number, default: undefined },
    volumeStep: { type: Number, default: undefined },
  },
  emits: ["ready", "play", "pause", "timeupdate", "ended", "error", "statechange"],
  setup(props, { emit, slots }) {
    const hostRef = shallowRef<HTMLElement | null>(null);

    const onEvent = (event: PlayerEvent): void => {
      switch (event.type) {
        case "loadedmetadata":
          emit("ready", event.detail);
          break;
        case "play":
          emit("play");
          break;
        case "pause":
          emit("pause");
          break;
        case "timeupdate":
          emit("timeupdate", event.detail);
          break;
        case "ended":
          emit("ended");
          break;
        case "error":
          emit("error", event.detail.error);
          break;
        case "statechange":
          emit("statechange", event.detail);
          break;
        default:
          break;
      }
    };

    const api = useUniversalPlayer({
      host: hostRef,
      source: computed(() => props.src),
      controls: computed(() => props.controls),
      theme: computed(() => props.theme),
      locale: computed(() => props.locale),
      autoplay: computed(() => props.autoplay),
      muted: computed(() => props.muted),
      loop: computed(() => props.loop),
      poster: computed(() => props.poster),
      volume: computed(() => props.volume),
      playbackRate: computed(() => props.playbackRate),
      chapters: computed(() => props.chapters),
      thumbnails: computed(() => props.thumbnails),
      captions: computed(() => props.captions),
      survey: computed(() => props.survey),
      playlist: computed(() => props.playlist),
      keyboard: computed(() => props.keyboard),
      clickToPlay: computed(() => props.clickToPlay),
      autoHideControls: computed(() => props.autoHideControls),
      seekStep: computed(() => props.seekStep),
      volumeStep: computed(() => props.volumeStep),
      onEvent,
    });

    return () =>
      h(
        "div",
        {
          ref: hostRef,
          "data-up-framework": "vue",
          "data-up-status": api.state.value.status,
        },
        slots.default?.(),
      );
  },
});
